package main

const page = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Shiraz Phone</title>
<style>
:root{font-family:system-ui,sans-serif;color:#eef2ff;background:#10131d}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(circle at 50% 0,#283454,#10131d 60%)}main{max-width:1050px;margin:auto;padding:30px 22px}header{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:32px}h1{font-size:1.5rem;margin:0}.brand{display:flex;align-items:center;gap:12px}.mark{width:32px;height:32px;border-radius:9px;background:linear-gradient(145deg,#7dd3fc,#8b5cf6)}.status{padding:7px 13px;border:1px solid #354157;border-radius:40px;color:#a9bbd8;font-size:.88rem}.status:before{content:'';display:inline-block;width:8px;height:8px;background:#eab308;border-radius:50%;margin-right:8px}.status.online:before{background:#34d399}.layout{display:grid;grid-template-columns:minmax(260px,400px) minmax(300px,1fr);gap:55px;align-items:start}.phone{width:min(100%,400px);margin:auto;padding:12px;border:3px solid #596274;border-radius:48px;background:#080b12;box-shadow:inset 0 0 0 2px #151a25,0 30px 80px #0008}.earpiece{height:17px;width:76px;border-radius:0 0 13px 13px;background:#080b12;position:absolute;top:0;left:50%;transform:translateX(-50%);z-index:2}.screen{position:relative;aspect-ratio:9/16;overflow:hidden;background:linear-gradient(155deg,#1e2946,#0c1427);border-radius:36px;touch-action:none;user-select:none}.screen img{display:block;width:100%;height:100%;object-fit:fill;visibility:hidden}.screen.ready img{visibility:visible}.empty{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;flex-direction:column;text-align:center;padding:28px;color:#a9b7d1}.empty .icon{font-size:48px;margin-bottom:12px}.empty strong{color:#fff;font-size:1.1rem}.screen.ready .empty{display:none}.nav{height:43px;display:flex;align-items:center;justify-content:space-around}.nav button{border:0;background:none;color:#dce5f6;font-size:25px;cursor:pointer;width:52px;height:36px}.nav button:hover{color:#7dd3fc}.panel{padding-top:12px}h2{font-size:1.9rem;line-height:1.15;margin:0 0 8px}.muted{color:#a7b4cc;line-height:1.5}.card{background:#20283a;border:1px solid #3a445b;border-radius:16px;padding:20px;margin-top:24px}label{display:block;font-weight:650;margin-bottom:12px}input[type=file]{display:block;width:100%;color:#cbd5e1;background:#141a2a;border:1px dashed #64748b;border-radius:10px;padding:15px}.primary{background:#8b5cf6;border:0;border-radius:9px;padding:12px 17px;color:white;font-weight:700;margin-top:14px;cursor:pointer}.primary:disabled{opacity:.5;cursor:wait}.note{font-size:.88rem;color:#a7b4cc}.logs{margin-top:20px}details summary{cursor:pointer;color:#bac9e4}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:300px;overflow:auto;background:#0d1220;border-radius:10px;padding:12px;color:#b9c5da;font-size:.75rem}@media(max-width:760px){.layout{grid-template-columns:1fr;gap:28px}.panel{order:-1}.phone{max-width:355px}main{padding:18px}header{margin-bottom:22px}}
</style></head><body><main><header><div class="brand"><span class="mark"></span><h1>Shiraz Phone</h1></div><span id="status" class="status">Connecting</span></header><div class="layout"><div class="phone"><div id="screen" class="screen"><div class="earpiece"></div><img id="frame" alt="Live Android app screen" draggable="false"><div class="empty"><div class="icon">◇</div><strong>Your app appears here</strong><span>Upload an APK to start the phone.</span></div></div><div class="nav"><button id="back" title="Back" aria-label="Back">‹</button><button id="stop" title="Stop app" aria-label="Stop app">○</button><button id="refresh" title="Refresh screen" aria-label="Refresh screen">↻</button></div></div><section class="panel"><h2>Run an Android app<br>in your browser</h2><p class="muted">Choose an APK. Shiraz runs it on this Linux server and shows its screen here. Touch or drag the phone screen to interact.</p><form id="form" class="card"><label for="apk">APK file</label><input id="apk" name="apk" type="file" accept=".apk,application/vnd.android.package-archive" required><button class="primary" id="send" disabled>Upload and run</button><p class="note">One app at a time · Up to 256 MiB · 30 minute session</p></form><div class="logs"><details><summary>Run log</summary><pre id="log"></pre></details></div></section></div></main>
<script>
const status=document.querySelector('#status'),screen=document.querySelector('#screen'),frame=document.querySelector('#frame'),send=document.querySelector('#send'),log=document.querySelector('#log');let ws,connected=false,drag=false;
function setStatus(message,online){status.textContent=message;status.classList.toggle('online',online)}
function connect(){ws=new WebSocket((location.protocol==='https:'?'wss://':'ws://')+location.host+'/ws');ws.onopen=()=>{connected=true;send.disabled=false;setStatus('Connected',true)};ws.onmessage=e=>{const msg=JSON.parse(e.data);if(msg.type==='status')setStatus(msg.message,true);else{log.textContent+=msg.message+'\n';log.scrollTop=log.scrollHeight;if(msg.type==='error')setStatus('Run failed',false)}};ws.onclose=()=>{connected=false;send.disabled=true;setStatus('Reconnecting',false);setTimeout(connect,1500)}}
connect();function input(action,x=0,y=0){if(connected)ws.send(JSON.stringify({action,x,y}))}function point(e){const r=screen.getBoundingClientRect();return{x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))}}
const controls=document.createElement('div');controls.className='card';controls.innerHTML='<label for="typing">Type into the app</label><input id="typing" type="text" maxlength="30" placeholder="Text for the focused field" style="width:100%;padding:10px;border-radius:8px;border:1px solid #64748b;background:#141a2a;color:white"><button id="type-send" class="primary" type="button">Send text</button><button id="enter" class="primary" type="button" style="margin-left:8px">Enter</button>';document.querySelector('.panel').insertBefore(controls,document.querySelector('.logs'));document.querySelector('#type-send').onclick=()=>{const field=document.querySelector('#typing');if(field.value&&connected){ws.send(JSON.stringify({action:'text',text:field.value}));field.value=''}};document.querySelector('#enter').onclick=()=>input('enter');
screen.addEventListener('pointerdown',e=>{if(!screen.classList.contains('ready'))return;drag=true;screen.setPointerCapture(e.pointerId);const p=point(e);input('fingerdown',p.x,p.y)});screen.addEventListener('pointermove',e=>{if(drag){const p=point(e);input('fingermove',p.x,p.y)}});function end(e){if(drag){drag=false;const p=point(e);input('fingerup',p.x,p.y)}}screen.addEventListener('pointerup',end);screen.addEventListener('pointercancel',end);document.querySelector('#back').onclick=()=>input('back');document.querySelector('#stop').onclick=()=>input('stop');document.querySelector('#refresh').onclick=()=>refresh();
async function refresh(){try{const response=await fetch('/frame.png?t='+Date.now(),{cache:'no-store'});if(!response.ok)return;const blob=await response.blob(),url=URL.createObjectURL(blob),old=frame.src;frame.onload=()=>{screen.classList.add('ready');if(old.startsWith('blob:'))URL.revokeObjectURL(old)};frame.src=url}catch{}}setInterval(refresh,350);
document.querySelector('#form').onsubmit=async e=>{e.preventDefault();send.disabled=true;log.textContent='';screen.classList.remove('ready');setStatus('Uploading',true);try{const response=await fetch('/upload',{method:'POST',body:new FormData(e.target)});if(!response.ok)throw Error((await response.text()).trim());setStatus('Starting',true)}catch(error){setStatus('Upload failed',false);log.textContent=error.message}finally{send.disabled=false}};
</script></body></html>`
